#!/usr/bin/env python3
from pathlib import Path
import re,sys

if len(sys.argv)!=3:
    raise SystemExit('usage: integrate-SOT-turn01-base25-ai.py <clean-base24-intermediate.html> <base25.html>')
src=Path(sys.argv[1]).read_text()
for marker in ['TURN01_BASE24_OWNER_GATE','async function openFolderSelector(opts)','async function renderIndex(p,silent=false)','async function renderPlan(p)','function openConfig(){','function renderInsights(p)','2-copy groups','3-copy groups','4+ copy groups','availableFolderSearch','selectorCommit','Current Plan','Previous / Stale Plan']:
    if marker not in src:
        raise SystemExit('Base25 clean integration contract missing '+marker)

def span(text,name):
    ms=list(re.finditer(r'(?m)^(?:async\s+)?function\s+'+re.escape(name)+r'\s*\(',text))
    if len(ms)!=1: raise SystemExit(f'function {name} ambiguous {len(ms)}')
    a=ms[0].start(); b=text.find('{',ms[0].end()); d=0; q=None; escp=False; i=b
    while i<len(text):
        c=text[i]
        if q:
            if escp: escp=False
            elif c=='\\': escp=True
            elif c==q: q=None
        else:
            if c in "'\"`": q=c
            elif c=='{': d+=1
            elif c=='}':
                d-=1
                if d==0:return a,i+1
        i+=1
    raise SystemExit('unbalanced '+name)

def repl(text,name,val):
    a,b=span(text,name)
    return text[:a]+val.rstrip()+text[b:]

src=src.replace('/* TURN01_BASE24_OWNER_GATE */','/* TURN01_BASE24_OWNER_GATE */\n/* TURN01_BASE25_OPERATIONAL_AI */',1)
src=src.replace('</style>',r'''
/* TURN01_BASE25_OPERATIONAL_AI */
.aiGrid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.aiProvider{border:1px solid var(--line);border-radius:10px;background:#111923;padding:11px}.aiProvider.active{border-color:var(--good)}.aiStatus{font-size:10px;margin-top:6px;color:var(--muted)}.aiStatus.good{color:var(--good)}.aiStatus.bad{color:var(--bad)}.aiCompose{display:grid;gap:8px}.aiCompose textarea{min-height:92px;resize:vertical}.aiAnswer{white-space:pre-wrap;word-break:break-word}.aiMeta{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.aiBadge{font-size:10px;border:1px solid var(--line);border-radius:999px;padding:3px 8px}.aiBadge.active{border-color:var(--good);color:var(--good)}@media(max-width:760px){.aiGrid{grid-template-columns:1fr}}
'''+"\n</style>",1)

helpers=r'''
const SOT_AI_SUPERVISOR=`You are the SOT storage-analysis supervisor. The SOT database and deterministic fingerprint/evidence records supplied in the following context are the factual authority. You are an analyst and advisor only: never act as filesystem authority, execution authority, or approval authority. Do not invent files, paths, hashes, capacities, volume state, duplicate groups, plan state, approvals, or execution outcomes. Any action you recommend is only a proposal and must remain subject to deterministic validation, SOT plan compilation, and required approval before execution. If evidence is missing, stale, contradictory, or insufficient, say so explicitly rather than filling gaps with assumptions. Preserve project boundaries and identify cross-project implications instead of silently resolving them. Explain recommendations using the supplied evidence and provenance.`;
const SOT_AI_KEYS={venice:'sot.ai.venice.key',openrouter:'sot.ai.openrouter.key',veniceModel:'sot.ai.venice.model',openrouterModel:'sot.ai.openrouter.model',veniceValidated:'sot.ai.venice.validated',openrouterValidated:'sot.ai.openrouter.validated',active:'sot.ai.active'};
function aiGet(k){return localStorage.getItem(k)||''}
function aiPut(k,v){if(v===null||v===undefined||v==='')localStorage.removeItem(k);else localStorage.setItem(k,String(v))}
function aiProviderState(provider){let key=aiGet(SOT_AI_KEYS[provider]),model=aiGet(SOT_AI_KEYS[provider+'Model']),validated=aiGet(SOT_AI_KEYS[provider+'Validated'])==='1',active=aiGet(SOT_AI_KEYS.active)===provider&&validated&&!!key&&!!model;return{provider,key,model,validated,active}}
function aiClearValidation(provider){aiPut(SOT_AI_KEYS[provider+'Validated'],'');if(aiGet(SOT_AI_KEYS.active)===provider)aiPut(SOT_AI_KEYS.active,'')}
function aiProviderLabel(provider){return provider==='venice'?'Venice.ai':'OpenRouter'}
async function aiLoadModels(provider,key){key=String(key||'').trim();if(!key)throw new Error('Enter the API key first.');if(provider==='venice'){let r=await fetch('https://api.venice.ai/api/v1/models',{cache:'no-store',headers:{'Authorization':'Bearer '+key}}),j={};try{j=await r.json()}catch{}if(!r.ok)throw new Error((j.error&&(j.error.message||j.error))||('Venice models '+r.status));let ids=(j.data||[]).map(x=>x.id).filter(Boolean).sort();if(!ids.length)throw new Error('No Venice models returned.');return ids}let auth=await fetch('https://openrouter.ai/api/v1/auth/key',{cache:'no-store',headers:{'Authorization':'Bearer '+key}}),aj={};try{aj=await auth.json()}catch{}if(!auth.ok)throw new Error((aj.error&&(aj.error.message||aj.error))||('OpenRouter key '+auth.status));let r=await fetch('https://openrouter.ai/api/v1/models',{cache:'no-store'}),j={};try{j=await r.json()}catch{}if(!r.ok)throw new Error('OpenRouter models '+r.status);let ids=(j.data||[]).map(x=>x.id).filter(Boolean).sort();if(!ids.length)throw new Error('No OpenRouter models returned.');return ids}
async function aiValidateProvider(provider,key,model){key=String(key||'').trim();model=String(model||'').trim();if(!key||!model)throw new Error('Key and model are required.');let url=provider==='venice'?'https://api.venice.ai/api/v1/chat/completions':'https://openrouter.ai/api/v1/chat/completions';let r=await fetch(url,{method:'POST',cache:'no-store',headers:{'Content-Type':'application/json','Authorization':'Bearer '+key},body:JSON.stringify({model,max_tokens:2,messages:[{role:'system',content:SOT_AI_SUPERVISOR},{role:'user',content:'Reply OK.'}]})}),j={};try{j=await r.json()}catch{}if(!r.ok)throw new Error((j.error&&(j.error.message||j.error))||(`${aiProviderLabel(provider)} validation ${r.status}`));if(!j.choices||!j.choices[0])throw new Error('Provider returned no completion.');aiPut(SOT_AI_KEYS[provider],key);aiPut(SOT_AI_KEYS[provider+'Model'],model);aiPut(SOT_AI_KEYS[provider+'Validated'],'1');aiPut(SOT_AI_KEYS.active,provider);return true}
function aiActiveProvider(){let p=aiGet(SOT_AI_KEYS.active);if(!['venice','openrouter'].includes(p))return null;let s=aiProviderState(p);return s.active?s:null}
function aiHistoryKey(token){return 'sot.ai.history.'+token}
function aiReadHistory(token){try{let x=JSON.parse(localStorage.getItem(aiHistoryKey(token))||'[]');return Array.isArray(x)?x.slice(-12):[]}catch{return[]}}
function aiWriteHistory(token,h){localStorage.setItem(aiHistoryKey(token),JSON.stringify((h||[]).slice(-12)))}
async function aiProjectEvidence(p){let safe=async path=>{try{return await api(path)}catch(e){return{unavailable:true,error:e.message}}};let token=encodeURIComponent(p.project_token),[review,plan,index,dups,detail]=await Promise.all([safe(`/turn01/projects/${token}/review`),safe(`/turn01/projects/${token}/plan`),safe(`/projects/${token}/fingerprint/status`),safe(`/turn01/projects/${token}/duplicates`),safe(`/turn01/projects/${token}`)]);let planItems=Array.isArray(plan.items)?plan.items.slice(0,100):[];return{captured_at:new Date().toISOString(),project:{project_token:p.project_token,project_name:p.project_name,evidence_revision:p.evidence_revision,processing_state:p.processing_state||p.status||''},project_detail:detail,review,plan:{state:plan.state,evidence_revision:plan.evidence_revision,item_count:Array.isArray(plan.items)?plan.items.length:0,items:planItems,error:plan.error},fingerprint:index,duplicates:dups}}
async function aiInferenceRequest(p,evidence,user){let active=aiActiveProvider();if(!active)throw new Error('No validated AI provider is active. Open Configuration and validate Venice or OpenRouter.');let history=aiReadHistory(p.project_token),context='SOT PROJECT / EVIDENCE CONTEXT\n'+JSON.stringify(evidence);let messages=[{role:'system',content:SOT_AI_SUPERVISOR},{role:'system',content:context},...history,{role:'user',content:user}];let url=active.provider==='venice'?'https://api.venice.ai/api/v1/chat/completions':'https://openrouter.ai/api/v1/chat/completions';let r=await fetch(url,{method:'POST',cache:'no-store',headers:{'Content-Type':'application/json','Authorization':'Bearer '+active.key},body:JSON.stringify({model:active.model,max_tokens:4000,messages})}),j={};try{j=await r.json()}catch{}if(!r.ok)throw new Error((j.error&&(j.error.message||j.error))||(`${aiProviderLabel(active.provider)} ${r.status}`));let answer=j.choices&&j.choices[0]&&j.choices[0].message&&j.choices[0].message.content;if(!answer)throw new Error('Provider returned no answer.');history.push({role:'user',content:user},{role:'assistant',content:answer});aiWriteHistory(p.project_token,history);return{answer,provider:active.provider,model:active.model}}
'''
insert=src.index('function openConfig(){')
src=src[:insert]+helpers+'\n'+src[insert:]

open_config=r'''async function openConfig(){let cfg={};try{cfg=await api('/admin/settings')}catch{}let target=cfg.target_root?[cfg.target_root]:[],backup=cfg.backup_root?[cfg.backup_root]:[];let modelCache={venice:[],openrouter:[]};function status(provider){let s=aiProviderState(provider);if(s.active)return`<span class="aiStatus good">ACTIVE · ${esc(s.model)}</span>`;if(s.validated)return`<span class="aiStatus good">Validated · ${esc(s.model)}</span>`;if(s.key)return`<span class="aiStatus">Configured — validation required</span>`;return`<span class="aiStatus">Not configured</span>`}function providerCard(provider){let s=aiProviderState(provider),label=aiProviderLabel(provider),models=modelCache[provider],opts=(models.length?models:(s.model?[s.model]:[])).map(m=>`<option value="${esc(m)}" ${m===s.model?'selected':''}>${esc(m)}</option>`).join('');return`<div class="aiProvider ${s.active?'active':''}" data-provider-card="${provider}"><h3 style="margin:0 0 8px">${label}</h3><div class="field"><label>API key — browser local only</label><input id="aiKey-${provider}" class="input" type="password" autocomplete="new-password" value="${esc(s.key)}"></div><div class="actions"><button id="aiLoad-${provider}" class="btn">Load models</button><select id="aiModel-${provider}" class="input" style="flex:1;min-width:180px"><option value="">— select model —</option>${opts}</select></div><div class="actions" style="margin-top:8px"><button id="aiValidate-${provider}" class="btn primary">Validate & activate</button><span id="aiStatus-${provider}">${status(provider)}</span></div></div>`}function draw(){openModal('Configuration',`<div class="compactCard"><h3>Default Target</h3><div class="mono">${esc(target[0]||'Not set')}</div><button id="defaultTarget" class="btn">Select</button></div><div class="compactCard" style="margin-top:8px"><h3>Default Backup</h3><div class="mono">${esc(backup[0]||'Not set')}</div><button id="defaultBackup" class="btn">Select</button></div><div class="section" style="margin-top:12px"><div class="sectionHead"><h2>Operational AI</h2></div><div class="sectionBody"><div class="notice" style="margin-bottom:10px">AI becomes active only after a real provider/model validation. Keys remain in this browser and are never written to the SOT database.</div><div class="aiGrid">${providerCard('venice')}${providerCard('openrouter')}</div></div></div>`,`<button class="btn" data-close>Cancel</button><button id="saveConfig" class="btn primary">Save storage defaults</button>`);$('defaultTarget').onclick=()=>openFolderSelector({role:'target',title:'Default Target',selected:target,doneLabel:'Use Default Target',onDone:a=>{target=a;draw()}});$('defaultBackup').onclick=()=>openFolderSelector({role:'backup',title:'Default Backup',selected:backup,doneLabel:'Use Default Backup',onDone:a=>{backup=a;draw()}});for(let provider of['venice','openrouter']){let keyEl=$('aiKey-'+provider),modelEl=$('aiModel-'+provider),statusEl=$('aiStatus-'+provider);keyEl.onchange=()=>{aiPut(SOT_AI_KEYS[provider],keyEl.value.trim());aiClearValidation(provider);draw()};modelEl.onchange=()=>{aiPut(SOT_AI_KEYS[provider+'Model'],modelEl.value);aiClearValidation(provider);draw()};$('aiLoad-'+provider).onclick=async()=>{statusEl.innerHTML='<span class="aiStatus">Loading models…</span>';try{let key=keyEl.value.trim();aiPut(SOT_AI_KEYS[provider],key);aiClearValidation(provider);modelCache[provider]=await aiLoadModels(provider,key);let prior=aiGet(SOT_AI_KEYS[provider+'Model']);if(!prior||!modelCache[provider].includes(prior))aiPut(SOT_AI_KEYS[provider+'Model'],modelCache[provider][0]);draw()}catch(e){statusEl.innerHTML=`<span class="aiStatus bad">${esc(e.message)}</span>`}};$('aiValidate-'+provider).onclick=async()=>{let key=keyEl.value.trim(),model=modelEl.value;statusEl.innerHTML='<span class="aiStatus">Validating real completion…</span>';try{await aiValidateProvider(provider,key,model);toast(`${aiProviderLabel(provider)} active`);draw()}catch(e){aiPut(SOT_AI_KEYS[provider],key);aiPut(SOT_AI_KEYS[provider+'Model'],model);aiClearValidation(provider);statusEl.innerHTML=`<span class="aiStatus bad">Validation failed: ${esc(e.message)}</span>`}}}$('saveConfig').onclick=async()=>{try{await api('/admin/settings',{method:'PUT',body:JSON.stringify({target_root:target[0]||'',backup_root:backup[0]||'',hash_workers:Number(cfg.hash_workers||4)})});closeModal();toast('Storage defaults saved')}catch(e){toast(e.message)}}}draw()}'''
src=repl(src,'openConfig',open_config)

insights=r'''async function renderInsights(p){let c=$('content'),active=aiActiveProvider();if(!active){c.innerHTML=`<div class="section"><div class="sectionHead"><h2>Insights / AI analyst</h2></div><div class="sectionBody"><div class="notice"><b>No validated AI provider is active.</b><div class="muted" style="margin-top:5px">Configure Venice or OpenRouter, load a model, and complete a real validation before inference is enabled.</div><button id="insightsConfig" class="btn primary" style="margin-top:10px">Open Configuration</button></div></div></div>`;$('insightsConfig').onclick=openConfig;return}c.innerHTML=`<div class="section"><div class="sectionHead"><h2>Insights / AI analyst</h2><span class="spacer"></span><span class="aiBadge active">${esc(aiProviderLabel(active.provider))} · ${esc(active.model)}</span></div><div class="sectionBody"><div class="notice" style="margin-bottom:10px">Primed with the SOT supervisor guardrails. Responses are advisory and grounded only in the project/evidence context supplied to the provider.</div><div class="aiCompose"><textarea id="aiQuestion" class="input" placeholder="Ask about duplicates, anomalies, plan implications, evidence gaps, or storage opportunities…"></textarea><div class="actions"><button id="aiAsk" class="btn primary">Analyze current evidence</button><button id="aiClearHistory" class="btn">Clear conversation</button><button id="aiConfig" class="btn">Provider</button></div><div id="aiEvidenceState" class="muted">Evidence is loaded at request time from the current SOT project state.</div><div id="aiAnswer" class="aiAnswer"></div></div></div></div>`;$('aiConfig').onclick=openConfig;$('aiClearHistory').onclick=()=>{localStorage.removeItem(aiHistoryKey(p.project_token));$('aiAnswer').textContent='Conversation cleared.'};$('aiAsk').onclick=async()=>{let q=$('aiQuestion').value.trim();if(!q)return;let btn=$('aiAsk'),out=$('aiAnswer'),meta=$('aiEvidenceState');btn.disabled=true;out.textContent='Analyzing…';try{let evidence=await aiProjectEvidence(p);meta.textContent=`Evidence revision ${Number(p.evidence_revision||0)} · captured ${new Date(evidence.captured_at).toLocaleString()}`;let r=await aiInferenceRequest(p,evidence,q);out.textContent=r.answer;meta.textContent+=` · ${aiProviderLabel(r.provider)} / ${r.model}`}catch(e){out.innerHTML=`<div class="errorBox">${esc(e.message)}</div>`}finally{btn.disabled=false}}}'''
src=repl(src,'renderInsights',insights)

required=['TURN01_BASE25_OPERATIONAL_AI','SOT_AI_SUPERVISOR','https://api.venice.ai/api/v1/models','https://openrouter.ai/api/v1/auth/key','Validate & activate','aiValidateProvider','aiActiveProvider',"messages=[{role:'system',content:SOT_AI_SUPERVISOR},{role:'system',content:context},...history,{role:'user',content:user}]",'No validated AI provider is active.','SOT PROJECT / EVIDENCE CONTEXT','Save storage defaults','Use Default Target','Use Default Backup']
for marker in required:
    if marker not in src: raise SystemExit('Base25 AI marker missing '+marker)
Path(sys.argv[2]).write_text(src)
print('Base-25 operational AI integrated into clean governed UI chain')
